617  struct hb_aat_apply_context_t :
   618         hb_dispatch_context_t<hb_aat_apply_context_t, bool, HB_DEBUG_APPLY>
   619  {
   620    inline const char *get_name (void) { return "APPLY"; }
   621    template <typename T>
   622    inline return_t dispatch (const T &obj) { return obj.apply (this); }
   623    static return_t default_return_value (void) { return false; }
   624    bool stop_sublookup_iteration (return_t r) const { return r; }
   625
   626    hb_font_t *font;
   627    hb_face_t *face;
   628    hb_buffer_t *buffer;
   629    hb_sanitize_context_t sanitizer;
   630
   631    /* Unused. For debug tracing only. */
   632    unsigned int lookup_index;
   633    unsigned int debug_depth;
   634
   635    inline hb_aat_apply_context_t (hb_font_t *font_,
   636                                   hb_buffer_t *buffer_,
   637                                   hb_blob_t *table) :
   638                  font (font_), face (font->face), buffer (buffer_),
   639                  sanitizer (), lookup_index (0), debug_depth (0)
   640    {
   641      sanitizer.init (table);
   642      sanitizer.set_num_glyphs (face->get_num_glyphs ());
   643      sanitizer.start_processing ();
   644    }
   645
   646    inline void set_lookup_index (unsigned int i) { lookup_index = i; }
   647
   648    inline ~hb_aat_apply_context_t (void)
   649    {
   650      sanitizer.end_processing ();
   651    }
   652  };
